  ('g5-c5-l3', 'g5-c5', 'Bài 27: Đường tròn. Chu vi và diện tích hình tròn', 'learn', 'Bán kính, đường kính; chu vi C = d × 3,14; diện tích S = r × r × 3,14', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Một cái nắp hộp hình tròn có bán kính 5 cm. Chu vi là 31,4 cm, diện tích là 78,5 cm². Số 3,14 thật kì diệu! ⭕"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Chu vi và diện tích hình tròn","explanation":"Hình tròn có tâm và bán kính r; đường kính d dài gấp đôi bán kính. Muốn tính chu vi hình tròn, ta lấy đường kính nhân với 3,14. Muốn tính diện tích hình tròn, ta lấy bán kính nhân với bán kính rồi nhân với 3,14.","points":["C = d × 3,14 hoặc C = r × 2 × 3,14.","S = r × r × 3,14.","r = 5 cm ⇒ C = 31,4 cm; S = 5 × 5 × 3,14 = 78,5 cm²."],"rule":"Chu vi dùng đường kính (hoặc bán kính × 2); diện tích dùng bán kính × bán kính."}},{"type":"visual","content":{"text":"Hình tròn: tâm O, bán kính r, đường kính d = 2 × r","circleParts":{"radius":3,"diameter":6,"showCenter":true,"pointLabels":{"center":"O"},"radiusLabel":"bán kính r","diameterLabel":"đường kính d","label":"Chu vi C = d × 3,14 · Diện tích S = r × r × 3,14"}}},{"type":"visual","content":{"planeShape":{"kind":"circle"},"text":"hình tròn bé học hôm nay có gì đặc biệt?\n· không có cạnh, không có đỉnh\n· tâm là điểm chính giữa\nBé tìm tâm, đo bán kính ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của hình tròn","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của hình tròn.","points":["hình tròn không có cạnh, không có đỉnh.","hình tròn có tâm là điểm chính giữa.","hình tròn có đường kính gấp đôi bán kính.","Cách kiểm tra: bé tìm tâm, đo bán kính; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 