  ('g5-c5-l5', 'g5-c5', 'Bài 29: Luyện tập chung', 'learn', 'Luyện tập tính diện tích hình tam giác, hình thang, chu vi và diện tích hình tròn', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ba công thức cần nhớ: tam giác S = a × h : 2; hình thang S = (a + b) × h : 2; hình tròn S = r × r × 3,14. 📏"}},{"type":"visual","content":{"text":"Bảng tổng hợp công thức hình phẳng","table":{"headers":["Hình","Công thức"],"rows":[["Tam giác","S = đáy × chiều cao : 2"],["Hình thang","S = (đáy lớn + đáy bé) × chiều cao : 2"],["Hình tròn (chu vi)","C = d × 3,14"],["Hình tròn (diện tích)","S = r × r × 3,14"]],"label":"Nhớ đơn vị diện tích là cm², m²…"}}},{"type":"visual","content":{"planeShape":{"kind":"circle"},"text":"hình tròn bé học hôm nay có gì đặc biệt?\n· không có cạnh, không có đỉnh\n· tâm là điểm chính giữa\nBé tìm tâm, đo bán kính ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của hình tròn","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của hình tròn.","points":["hình tròn không có cạnh, không có đỉnh.","hình tròn có tâm là điểm chính giữa.","hình tròn có đường kính gấp đôi bán kính.","Cách kiểm tra: bé tìm tâm, đo bán kính; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước làm bài — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","mascotHint":"Người tính giỏi luôn thử lại: cộng thì lấy kết quả trừ đi một số hạng."}},{"type":"quiz","content":{"question":"Hình nào không có cạnh, không có đỉnh?","options":["hình tròn","hình khối lập phương","hình khối hộp chữ nhật","hình khối trụ"],"answer":"hình tròn","mascotHint":"hình tròn: không có cạnh, không có đỉnh · tâm là điểm chính giữa · đường kính gấp đôi bán kính."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình tròn và hình tam giác và hình thang. Hình nào có tâm là điểm chính giữa?","options":["hình tròn","hình khối lập phương","hình khối hộp chữ nhật","hình khối trụ"],"answer":"hình tròn","mascotHint":"Đáp án là hình tròn: không có cạnh, không có đỉnh · tâm là điểm chính giữa · đường kính gấp đôi bán kính."}},{"type":"quiz","content":{"question":"Hình tam giác có đáy 9 m, chiều cao 6 m. Diện tích là:","options":["27 m²","54 m²","15 m²","30 m²"],"answer":"27 m²","mascotHint":"9 × 6 : 2 = 54 : 2 = 27 (m²)."}},{"type":"quiz","content":{"question":"Hình thang có đáy lớn 14 dm, đáy bé 6 dm, chiều cao 10 dm. Diện tích là:","options":["100 dm²","200 dm²","120 dm²","80 dm²"],"answer":"100 dm²","mascotHint":"(14 + 6) × 10 : 2 = 20 × 10 : 2 = 100 (dm²)."}},{"type":"quiz","content":{"question":"Hình tròn có đường kính 6 cm. Chu vi hình tròn là:","options":["18,84 cm","9,42 cm","37,68 cm","28,26 cm"],"answer":"18,84 cm","mascotHint":"C = 6 × 3,14 = 18,84 (cm)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Tam giác và hình thang: nhớ chia 2.","Hình tròn: chu vi dùng d, diện tích dùng r × r.","Ghi đúng đơn vị đo diện tích."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l1', 'g5-c6', 'Bài 30: Ôn tập số thập phân', 'learn', 'Ôn tập đọc viết, so sánh, làm tròn số thập phân và đổi đơn vị đo', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hết học kì 1, cùng ôn lại số thập phân: 1,25 m là bao nhiêu xăng-ti-mét nhỉ? 📏"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Số thập phân","explanation":"Ôn lại cấu tạo số thập phân (phần nguyên, phần thập phân), cách so sánh hai số thập phân và cách làm tròn số thập phân đến một hàng cho trước.","points":["So sánh: so phần nguyên trước, rồi so từng hàng phần thập phân.","Làm tròn: xét chữ số liền sau hàng làm tròn.","1,25 m = 125 cm."],"rule":"Viết thêm chữ số 0 tận cùng bên phải không làm đổi giá trị."}},{"type":"visual","content":{"text":"Ôn tập số thập phân","table":{"headers":["Nội dung","Ví dụ"],"rows":[["Cấu tạo","7,35 gồm 7 đơn vị, 3 phần mười, 5 phần trăm"],["So sánh","4,5 < 4,52"],["Làm tròn","6,78 ≈ 6,8 (hàng phần mười)"],["Đổi đơn vị","1,25 m = 125 cm"]],"label":"Kiểm tra lại bằng cách đổi sang phân số thập phân"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Số 7,35 gồm những hàng nào?","options":["7 đơn vị, 3 phần mười, 5 phần trăm","7 đơn vị, 5 phần mười, 3 phần trăm","7 phần mười, 3 phần trăm","7 chục, 3 đơn vị, 5 phần mười"],"answer":"7 đơn vị, 3 phần mười, 5 phần trăm","mascotHint":"Chữ số đầu sau dấu phẩy là phần mười, tiếp theo là phần trăm."}},{"type":"quiz","content":{"question":"1,25 m bằng bao nhiêu xăng-ti-mét?","options":["125 cm","12,5 cm","1 250 cm","1025 cm"],"answer":"125 cm","mascotHint":"1 m = 100 cm; 0,25 m = 25 cm nên 1,25 m = 125 cm."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Nắm cấu tạo số thập phân.","So sánh phần nguyên rồi phần thập phân.","Làm tròn đúng hàng và đổi đơn vị chính xác."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l2', 'g5-c6', 'Bài 31: Ôn tập các phép tính với số thập phân', 'learn', 'Ôn tập cộng, trừ, nhân, chia số thập phân và tính giá trị biểu thức', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Một cửa hàng bán 3,5 kg táo giá 45 000 đồng một ki-lô-gam. Phải tính 3,5 × 45 000 = 157 500 đồng! 🍎"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Bốn phép tính với số thập phân","explanation":"Ôn lại cách đặt tính và tính cộng, trừ, nhân, chia số thập phân; cách tính giá trị biểu thức và vận dụng vào bài toán mua bán.","points":["Cộng, trừ: các chữ số cùng hàng thẳng cột, dấu phẩy thẳng cột.","Nhân: đếm chữ số phần thập phân để đặt dấu phẩy ở tích.","Chia: dời dấu phẩy khi chia cho số thập phân."],"rule":"Biểu thức: tính trong ngoặc trước, nhân chia trước, cộng trừ sau."}},{"type":"visual","content":{"text":"Ôn tập các phép tính với số thập phân","table":{"headers":["Phép tính","Kết quả"],"rows":[["4,75 + 2,5","7,25"],["9,6 − 3,45","6,15"],["3,5 × 45 000","157 500"],["7,2 : 1,2",6]],"label":"Thử lại kết quả bằng phép tính ngược"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Tính: 4,75 + 2,5 = ?","options":["7,25","6,25","7,15","72,5"],"answer":"7,25","mascotHint":"2,5 = 2,50; 4,75 + 2,50 = 7,25."}},{"type":"quiz","content":{"question":"3,5 kg táo giá 45 000 đồng một ki-lô-gam. Số tiền phải trả là:","options":["157 500 đồng","157 000 đồng","145 000 đồng","1 575 000 đồng"],"answer":"157 500 đồng","mascotHint":"3,5 × 45 000 = 157 500 (đồng)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Đặt dấu phẩy đúng trong mỗi phép tính.","Tính giá trị biểu thức theo thứ tự.","Vận dụng vào bài toán mua bán thực tế."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l3', 'g5-c6', 'Bài 32: Ôn tập một số hình phẳng', 'learn', 'Ôn tập đặc điểm hình tam giác, hình thang, hình tròn và các hình đã học', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Nhìn vào hình vẽ: đâu là tam giác vuông, đâu là hình thang? Cùng ôn lại đặc điểm các hình phẳng! 📐"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Các hình phẳng đã học","explanation":"Nhắc lại đặc điểm của hình tam giác, hình thang, hình tròn và các hình tứ giác đã học ở các lớp dưới: số cạnh, số đỉnh, cặp cạnh song song, góc vuông.","points":["Tam giác: 3 cạnh, 3 đỉnh; tam giác vuông có 1 góc vuông.","Hình thang: có một cặp cạnh đối diện song song.","Hình tròn: tâm, bán kính, đường kính."],"rule":"Quan sát cạnh và góc để nhận biết hình."}},{"type":"visual","content":{"text":"Hình thang có hai đáy song song","planeShape":{"kind":"trapezoid","labels":["đáy lớn","đáy bé","chiều cao"],"formula":"Hai đáy song song với nhau"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài đo lường và đổi đơn vị đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc đơn vị đang có và đơn vị cần đổi.","Bước 2 — Viết bậc thang đơn vị ra giấy để thấy phải đi mấy bậc.","Bước 3 — Đi xuống (ra đơn vị bé hơn) thì NHÂN; đi lên (ra đơn vị lớn hơn) thì CHIA.","Bước 4 — Viết kết quả kèm đơn vị và kiểm tra lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["1 m","= 100 cm"],["1 kg","= 1 000 g"],["1 l","= 1 000 ml"]]},"text":"Bảng nhớ nhanh — đo lường và đổi đơn vị\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Đổi số đo từ đơn vị lớn sang đơn vị bé hơn thì bé làm phép gì?","options":["Nhân","Chia","Cộng","Trừ"],"answer":"Nhân","mascotHint":"Đơn vị bé hơn thì số đo phải nhiều hơn: 1 m đổi ra cm được 100 cm — đó là phép nhân."}},{"type":"quiz","content":{"question":"Hình tam giác vuông có đặc điểm gì?","options":["Có một góc vuông","Có ba góc vuông","Có bốn cạnh bằng nhau","Không có góc vuông"],"answer":"Có một góc vuông","mascotHint":"Tam giác vuông có một góc vuông, hai cạnh góc vuông vuông góc với nhau."}},{"type":"quiz","content":{"question":"Hình tròn có đường kính 8 cm thì bán kính là:","options":["4 cm","8 cm","16 cm","2 cm"],"answer":"4 cm","mascotHint":"Bán kính bằng một nửa đường kính: 8 : 2 = 4 (cm)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Nhận biết hình qua cạnh và góc.","d = 2 × r.","Hình thang có một cặp cạnh song song."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l4', 'g5-c6', 'Bài 33: Ôn tập diện tích, chu vi một số hình phẳng', 'learn', 'Ôn tập công thức chu vi, diện tích các hình phẳng đã học', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Một sân hình chữ nhật dài 20 m, rộng 15 m. Chu vi 70 m, diện tích 300 m². Cùng ôn lại các công thức nhé! 🏟️"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Chu vi và diện tích các hình","explanation":"Ôn tập công thức tính chu vi, diện tích hình chữ nhật, hình vuông, hình tam giác, hình thang và hình tròn để giải các bài toán thực tế.","points":["Hình chữ nhật: P = (a + b) × 2; S = a × b.","Tam giác: S = a × h : 2; hình thang: S = (a + b) × h : 2.","Hình tròn: C = d × 3,14; S = r × r × 3,14."],"rule":"Đơn vị chu vi là cm, m…; đơn vị diện tích là cm², m²…"}},{"type":"visual","content":{"text":"Công thức chu vi và diện tích","table":{"headers":["Hình","Chu vi","Diện tích"],"rows":[["Hình vuông","cạnh × 4","cạnh × cạnh"],["Hình chữ nhật","(dài + rộng) × 2","dài × rộng"],["Tam giác","tổng ba cạnh","đáy × chiều cao : 2"],["Hình thang","tổng bốn cạnh","(đáy lớn + đáy bé) × cao : 2"]],"label":"Chu vi là tổng độ dài các cạnh"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Sân hình chữ nhật dài 20 m, rộng 15 m. Chu vi sân là:","options":["70 m","35 m","300 m","140 m"],"answer":"70 m","mascotHint":"(20 + 15) × 2 = 70 (m)."}},{"type":"quiz","content":{"question":"Sân hình chữ nhật dài 20 m, rộng 15 m. Diện tích sân là:","options":["300 m²","70 m²","35 m²","600 m²"],"answer":"300 m²","mascotHint":"20 × 15 = 300 (m²)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Chu vi = tổng độ dài các cạnh.","Diện tích: nhớ chia 2 với tam giác và hình thang.","Đổi về cùng đơn vị trước khi tính."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l5', 'g5-c6', 'Bài 34: Ôn tập đo lường', 'learn', 'Ôn tập đơn vị đo độ dài, khối lượng, diện tích, thời gian và đổi đơn vị', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Một bao gạo nặng 0,75 tạ. Đổi ra ki-lô-gam là 75 kg. Cùng ôn lại bảng đơn vị đo! ⚖️"}},{"type":"concept","content":{"badge":"Ôn Tập","title":"Các đơn vị đo lường","explanation":"Ôn tập quan hệ giữa các đơn vị đo độ dài, khối lượng, diện tích và thời gian; luyện đổi đơn vị và viết số đo dưới dạng số thập phân.","points":["1 tấn = 10 tạ = 1 000 kg.","1 km² = 100 ha; 1 ha = 10 000 m².","1 giờ = 60 phút; 1 phút = 60 giây."],"rule":"Đơn vị lớn sang bé thì nhân; bé sang lớn thì chia."}},{"type":"visual","content":{"text":"Đổi đơn vị đo lường","table":{"headers":["Số đo","Đổi đơn vị"],"rows":[["0,75 tạ","75 kg"],["2,5 tấn","2 500 kg"],["1,5 giờ","90 phút"],["3 ha","30 000 m²"]],"label":"Dùng số thập phân để viết gọn số đo"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"0,75 tạ bằng bao nhiêu ki-lô-gam?","options":["75 kg","7,5 kg","750 kg","0,75 kg"],"answer":"75 kg","mascotHint":"1 tạ = 100 kg nên 0,75 tạ = 75 kg."}},{"type":"quiz","content":{"question":"1,5 giờ bằng bao nhiêu phút?","options":["90 phút","150 phút","75 phút","60 phút"],"answer":"90 phút","mascotHint":"1 giờ = 60 phút; 0,5 giờ = 30 phút nên 1,5 giờ = 90 phút."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Thuộc quan hệ giữa các đơn vị đo.","Đổi đơn vị đúng phép nhân, chia.","Viết số đo gọn bằng số thập phân."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c6-l6', 'g5-c6', 'Bài 35: Ôn tập chung', 'learn', 'Ôn tập tổng hợp kiến thức học kì 1: số thập phân, phép tính, hình học, đo lường', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Sẵn sàng cho kì thi? Cùng nhau ôn tập tổng hợp toàn bộ kiến thức học kì 1 nào! 🎯"}},{"type":"visual","content":{"text":"Bảng tổng hợp học kì 1","table":{"headers":["Nội dung","Điều cần nhớ"],"rows":[["Số thập phân","so sánh, làm tròn, đổi đơn vị"],["Bốn phép tính","đặt dấu phẩy đúng vị trí"],["Hình phẳng","công thức chu vi, diện tích"],["Đo lường","đổi đơn vị theo bậc"]],"label":"Ôn kĩ phần đặt tính với số thập phân"}}},{"type":"visual","content":{"cotTinh":{"left":125,"right":4,"sign":"×","remember":true},"text":"Bé tự đặt tính: 125 × 4\nhàng đơn vị 5 × 4 = 20, viết 0 nhớ 2\nhàng chục 2 × 4 + 2 (nhớ) = 10, viết 0 nhớ 1\nhàng trăm 1 × 4 + 1 (nhớ) = 5, viết 5\nVậy 125 × 4 = 500."}},{"type":"concept","content":{"badge":"Chú Ý","title":"Vì sao ra 480 là sai?","explanation":"480 là kết quả khi bé quên nhớ khi nhân từng hàng. Đây là lỗi hay gặp nhất của dạng nhân này.","points":["Lỗi — quên nhớ khi nhân từng hàng: hàng đơn vị 5 × 4 = 20, viết 0 nhớ 2. Kết quả đúng phải là 500.","Cách tránh: làm xong một hàng thì ghi/xoá số nhớ NGAY, đừng để sang hàng sau mới nhớ.","Tự kiểm tra: 500 : 4 phải bằng 125."]}},{"type":"quiz","content":{"question":"158 × 4 bằng bao nhiêu?","options":[402,631,632,633],"answer":632,"mascotHint":"hàng đơn vị 8 × 4 = 32, viết 2 nhớ 3. Kết quả 632."}},{"type":"quiz","content":{"question":"Tính: 12,5 × 4 = ?","options":["50","5","500","45"],"answer":"50","mascotHint":"125 × 4 = 500; một chữ số phần thập phân ⇒ 50,0 = 50."}},{"type":"quiz","content":{"question":"Hình tròn có bán kính 10 cm. Diện tích hình tròn là:","options":["314 cm²","31,4 cm²","62,8 cm²","100 cm²"],"answer":"314 cm²","mascotHint":"S = 10 × 10 × 3,14 = 314 (cm²)."}},{"type":"quiz","content":{"question":"Làm tròn số 8,567 đến hàng phần trăm:","options":["8,57","8,56","8,6","9"],"answer":"8,57","mascotHint":"Chữ số hàng phần nghìn là 7 nên 8,567 ≈ 8,57."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Nắm chắc số thập phân và bốn phép tính.","Thuộc công thức hình phẳng.","Đổi đơn vị đo thành thạo."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l1', 'g5-c7', 'Bài 36: Tỉ số. Tỉ số phần trăm', 'learn', 'Nhận biết tỉ số của hai số và cách viết tỉ số dưới dạng phân số, tỉ số phần trăm', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Trong bến xe có 3 ô tô điện và 4 ô tô chạy bằng xăng. Tỉ số giữa số ô tô điện và số ô tô ở bến là 3 : 7. 🚌"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tỉ số. Tỉ số phần trăm","explanation":"Tỉ số của hai số a và b là kết quả so sánh số này với số kia, viết là a : b hoặc a/b (b khác 0). Tỉ số phần trăm là tỉ số được viết dưới dạng phần trăm, có mẫu số là 100.","points":["Tỉ số của 3 và 7 là 3 : 7 hay 3/7.","3 : 4 = 0,75 = 75%.","1/2 = 50/100 = 50%."],"rule":"Tỉ số phần trăm có mẫu số là 100."}},{"type":"visual","content":{"text":"Tỉ số và tỉ số phần trăm","table":{"headers":["So sánh","Tỉ số","Tỉ số phần trăm"],"rows":[["3 so với 4","3 : 4","75%"],["1 so với 2","1 : 2","50%"],["1 so với 4","1 : 4","25%"],["7 so với 10","7 : 10","70%"]],"label":"0,75 = 75/100 = 75%"}}},{"type":"visual","content":{"cotTinh":{"left":3,"right":4,"sign":"+","remember":true},"text":"Bé tự đặt tính: 3 + 4\nhàng đơn vị 3 + 4 = 7, viết 7\nVậy 3 + 4 = 7."}},{"type":"quiz","content":{"question":"7 + 1 bằng bao nhiêu?","options":[7,8,9,10],"answer":8,"mascotHint":"hàng đơn vị 7 + 1 = 8, viết 8. Kết quả 8."}},{"type":"quiz","content":{"question":"Trong bến có 3 ô tô điện và 4 ô tô chạy xăng. Tỉ số của số ô tô điện và số ô tô ở bến là:","options":["3 : 7","4 : 7","3 : 4","7 : 3"],"answer":"3 : 7","mascotHint":"Số ô tô ở bến là 3 + 4 = 7 nên tỉ số là 3 : 7."}},{"type":"quiz","content":{"question":"Viết 3 : 4 thành tỉ số phần trăm:","options":["75%","34%","43%","25%"],"answer":"75%","mascotHint":"3 : 4 = 0,75 = 75/100 = 75%."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Tỉ số của a và b là a : b hay a/b.","Tỉ số phần trăm có mẫu số 100.","Đổi phân số, số thập phân thành phần trăm."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l2', 'g5-c7', 'Bài 37: Tỉ lệ bản đồ và ứng dụng', 'learn', 'Đọc tỉ lệ bản đồ và tính độ dài thật, độ dài thu nhỏ', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bản đồ ghi tỉ lệ 1 : 1 000 000. Vậy 1 cm trên bản đồ tương ứng 1 000 000 cm ngoài thực tế — tức 10 km! 🗺️"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tỉ lệ bản đồ","explanation":"Tỉ lệ bản đồ cho biết khoảng cách trên bản đồ đã được thu nhỏ bao nhiêu lần so với độ dài thật. Tỉ lệ 1 : a nghĩa là 1 đơn vị trên bản đồ ứng với a đơn vị ngoài thực tế.","points":["Tỉ lệ 1 : 1 000 000 ⇒ 1 cm trên bản đồ = 1 000 000 cm = 10 km thực tế.","Độ dài thật = độ dài trên bản đồ × mẫu số của tỉ lệ.","Độ dài thu nhỏ = độ dài thật : mẫu số của tỉ lệ."],"rule":"Tỉ lệ càng nhỏ thì bản đồ càng thu gọn nhiều."}},{"type":"visual","content":{"text":"Ứng dụng tỉ lệ bản đồ","table":{"headers":["Tỉ lệ bản đồ","Độ dài trên bản đồ","Độ dài thực tế"],"rows":[["1 : 1 000 000","1 cm","10 km"],["1 : 500","2 cm","10 m"],["1 : 200","3 cm","6 m"],["1 : 5 000","4 cm","200 m"]],"label":"Đổi đơn vị sau khi tính: 500 cm = 5 m"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Bản đồ tỉ lệ 1 : 500, độ dài trên bản đồ 2 cm. Độ dài thực tế là:","options":["10 m","1 000 m","10 cm","1 m"],"answer":"10 m","mascotHint":"2 × 500 = 1 000 cm = 10 m."}},{"type":"quiz","content":{"question":"Bản đồ tỉ lệ 1 : 1 000 000, độ dài thật 20 km thì độ dài trên bản đồ là:","options":["2 cm","20 cm","2 m","200 cm"],"answer":"2 cm","mascotHint":"20 km = 2 000 000 cm; 2 000 000 : 1 000 000 = 2 (cm)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Tỉ lệ bản đồ cho biết mức thu nhỏ.","Độ dài thật = độ dài bản đồ × mẫu số tỉ lệ.","Đổi về cùng đơn vị rồi mới kết luận."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l3', 'g5-c7', 'Bài 38: Tìm hai số khi biết tổng và tỉ số của hai số đó', 'learn', 'Giải bài toán tìm hai số khi biết tổng và tỉ số bằng sơ đồ đoạn thẳng', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Hai bạn có tất cả 45 viên bi, số bi của bạn thứ nhất bằng 2/3 số bi của bạn thứ hai. Mỗi bạn có bao nhiêu viên bi? 🔵"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Bài toán tổng – tỉ","explanation":"Để giải bài toán tìm hai số khi biết tổng và tỉ số, ta vẽ sơ đồ đoạn thẳng biểu diễn hai số theo tỉ số đã cho, tìm tổng số phần bằng nhau, rồi tìm giá trị một phần và từng số.","points":["Bước 1: vẽ sơ đồ theo tỉ số.","Bước 2: tìm tổng số phần bằng nhau.","Bước 3: giá trị một phần = tổng : tổng số phần.","Bước 4: số bé = giá trị một phần × số phần của số bé."],"rule":"Kiểm tra: tổng hai số tìm được phải bằng tổng đã cho."}},{"type":"visual","content":{"text":"Ví dụ: tổng 45, tỉ số 2/3","table":{"headers":["Bước","Phép tính","Kết quả"],"rows":[["Tổng số phần","2 + 3",5],["Giá trị một phần","45 : 5",9],["Số bé","9 × 2",18],["Số lớn","9 × 3",27]],"label":"Thử lại: 18 + 27 = 45 ✓"}}},{"type":"visual","content":{"cotTinh":{"left":9,"right":2,"sign":"×","remember":true},"text":"Bé tự đặt tính: 9 × 2\nhàng đơn vị 9 × 2 = 18, viết 8 nhớ 1\ncòn nhớ 1 ở hàng cao hơn, viết 1\nVậy 9 × 2 = 18."}},{"type":"quiz","content":{"question":"4 × 5 bằng bao nhiêu?","options":[19,20,21,22],"answer":20,"mascotHint":"hàng đơn vị 4 × 5 = 20, viết 0 nhớ 2. Kết quả 20."}},{"type":"quiz","content":{"question":"Hai bạn có tất cả 45 viên bi, tỉ số là 2/3. Số bi của hai bạn lần lượt là:","options":["18 viên và 27 viên","15 viên và 30 viên","20 viên và 25 viên","9 viên và 36 viên"],"answer":"18 viên và 27 viên","mascotHint":"Tổng số phần 5 ⇒ một phần 9 ⇒ 9 × 2 = 18 và 9 × 3 = 27."}},{"type":"quiz","content":{"question":"Một lớp có 35 học sinh, số học sinh nữ bằng 3/4 số học sinh nam. Số học sinh nam là:","options":["20 bạn","15 bạn","21 bạn","14 bạn"],"answer":"20 bạn","mascotHint":"Tổng số phần 3 + 4 = 7 ⇒ một phần 5 ⇒ nam 4 × 5 = 20 (bạn)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Vẽ sơ đồ theo tỉ số.","Tìm tổng số phần bằng nhau.","Tính giá trị một phần rồi tính từng số."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l4', 'g5-c7', 'Bài 39: Tìm hai số khi biết hiệu và tỉ số của hai số đó', 'learn', 'Giải bài toán tìm hai số khi biết hiệu và tỉ số bằng sơ đồ đoạn thẳng', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Số lớn hơn số bé 12 đơn vị, tỉ số giữa hai số là 5/3. Hai số đó là bao nhiêu nhỉ? 🔍"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Bài toán hiệu – tỉ","explanation":"Với bài toán tìm hai số khi biết hiệu và tỉ số, ta vẽ sơ đồ đoạn thẳng, tìm hiệu số phần bằng nhau, rồi tìm giá trị một phần và từng số.","points":["Hiệu số phần = số phần của số lớn − số phần của số bé.","Giá trị một phần = hiệu : hiệu số phần.","Số bé = giá trị một phần × số phần của số bé."],"rule":"Kiểm tra: hiệu hai số tìm được phải bằng hiệu đã cho."}},{"type":"visual","content":{"text":"Ví dụ: hiệu 12, tỉ số 5/3","table":{"headers":["Bước","Phép tính","Kết quả"],"rows":[["Hiệu số phần","5 − 3",2],["Giá trị một phần","12 : 2",6],["Số bé","6 × 3",18],["Số lớn","6 × 5",30]],"label":"Thử lại: 30 − 18 = 12 ✓"}}},{"type":"visual","content":{"cotTinh":{"left":6,"right":3,"sign":"×","remember":true},"text":"Bé tự đặt tính: 6 × 3\nhàng đơn vị 6 × 3 = 18, viết 8 nhớ 1\ncòn nhớ 1 ở hàng cao hơn, viết 1\nVậy 6 × 3 = 18."}},{"type":"quiz","content":{"question":"8 × 3 bằng bao nhiêu?","options":[4,23,24,25],"answer":24,"mascotHint":"hàng đơn vị 8 × 3 = 24, viết 4 nhớ 2. Kết quả 24."}},{"type":"quiz","content":{"question":"Hiệu hai số là 12, tỉ số là 5/3. Hai số đó là:","options":["18 và 30","15 và 27","12 và 24","20 và 32"],"answer":"18 và 30","mascotHint":"Hiệu số phần 2 ⇒ một phần 6 ⇒ 6 × 3 = 18 và 6 × 5 = 30."}},{"type":"quiz","content":{"question":"Mẹ hơn con 28 tuổi, tuổi mẹ gấp 5 lần tuổi con. Tuổi con là:","options":["7 tuổi","5 tuổi","8 tuổi","14 tuổi"],"answer":"7 tuổi","mascotHint":"Hiệu số phần 5 − 1 = 4 ⇒ một phần 7 ⇒ tuổi con 7 tuổi."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Vẽ sơ đồ theo tỉ số.","Tìm hiệu số phần bằng nhau.","Tính giá trị một phần rồi tính từng số."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l5', 'g5-c7', 'Bài 40: Tìm tỉ số phần trăm của hai số', 'learn', 'Tìm tỉ số phần trăm của hai số bằng cách lấy số thứ nhất chia số thứ hai rồi nhân với 100', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Lớp có 25 học sinh, trong đó 20 bạn thích bóng đá. Vậy số bạn thích bóng đá chiếm bao nhiêu phần trăm? ⚽"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tìm tỉ số phần trăm của hai số","explanation":"Muốn tìm tỉ số phần trăm của hai số, ta tìm thương của hai số đó, nhân thương với 100 rồi viết thêm kí hiệu % vào bên phải kết quả.","points":["20 : 25 = 0,8; 0,8 × 100 = 80; vậy 80%.","Trong thực hành, ta có thể viết gọn: 20 : 25 × 100 = 80%.","Kết quả thường lấy đến hai chữ số ở phần thập phân."],"rule":"Thương × 100 rồi thêm kí hiệu %."}},{"type":"visual","content":{"text":"Tỉ số phần trăm của hai số","table":{"headers":["Bài toán","Phép tính","Tỉ số phần trăm"],"rows":[["20 và 25","20 : 25 × 100","80%"],["15 và 60","15 : 60 × 100","25%"],["45 và 50","45 : 50 × 100","90%"],["7 và 20","7 : 20 × 100","35%"]],"label":"Kiểm tra: kết quả phải có kí hiệu %"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé 