  ('g5-c7-l6', 'g5-c7', 'Bài 41: Tìm giá trị phần trăm của một số', 'learn', 'Tìm giá trị phần trăm của một số rồi vận dụng vào tính tiền, giảm giá', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Một chiếc áo giá 400 000 đồng đang giảm 10%. Vậy giảm bao nhiêu tiền và phải trả bao nhiêu? 🛍️"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Tìm giá trị phần trăm của một số","explanation":"Muốn tìm giá trị phần trăm của một số, ta lấy số đó chia cho 100 rồi nhân với số phần trăm, hoặc lấy số đó nhân với số phần trăm rồi chia cho 100.","points":["10% của 400 000 = 400 000 : 100 × 10 = 40 000 (đồng).","Giá sau khi giảm = 400 000 − 40 000 = 360 000 (đồng).","25% của 200 kg = 200 : 100 × 25 = 50 (kg)."],"rule":"Giá trị % = số đó : 100 × số phần trăm."}},{"type":"visual","content":{"text":"Tìm giá trị phần trăm của một số","table":{"headers":["Bài toán","Phép tính","Kết quả"],"rows":[["10% của 400 000","400 000 : 100 × 10","40 000"],["25% của 200 kg","200 : 100 × 25","50 kg"],["15% của 60 l","60 : 100 × 15","9 l"],["50% của 8 m","8 : 100 × 50","4 m"]],"label":"Nhớ đơn vị đo của kết quả"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"10% của 400 000 đồng là bao nhiêu?","options":["40 000 đồng","4 000 đồng","400 000 đồng","10 000 đồng"],"answer":"40 000 đồng","mascotHint":"400 000 : 100 × 10 = 40 000 (đồng)."}},{"type":"quiz","content":{"question":"Chiếc áo 400 000 đồng giảm 10%. Giá phải trả sau khi giảm là:","options":["360 000 đồng","390 000 đồng","40 000 đồng","300 000 đồng"],"answer":"360 000 đồng","mascotHint":"Giảm 40 000 đồng; 400 000 − 40 000 = 360 000 (đồng)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Giá trị % = số : 100 × số phần trăm.","Giá sau khi giảm = giá gốc − số tiền giảm.","Ghi đúng đơn vị của kết quả."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l7', 'g5-c7', 'Bài 42: Máy tính cầm tay', 'learn', 'Làm quen với các phím của máy tính cầm tay và dùng máy để tính toán, tính phần trăm', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Rô-bốt vừa được tặng một chiếc máy tính cầm tay. Trên máy có phím số, phím phép tính, phím % và phím dấu phẩy. Cùng khám phá! 🤖"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Các phím của máy tính cầm tay","explanation":"Máy tính cầm tay có các phím số từ 0 đến 9, phím dấu phẩy để nhập số thập phân, các phím cộng trừ nhân chia, phím bằng và phím phần trăm. Ta nhập phép tính theo đúng thứ tự hiện trên máy rồi bấm phím bằng để xem kết quả.","points":["Phím dấu phẩy dùng để nhập phần thập phân.","Bấm lần lượt: số, phép tính, số, rồi phím bằng.","Phím % giúp tính nhanh tỉ số phần trăm."],"rule":"Nhập đúng thứ tự và kiểm tra kết quả bằng ước lượng."}},{"type":"visual","content":{"text":"Nhập phép tính trên máy","table":{"headers":["Bấm phím","Điều xảy ra"],"rows":[["12 , 5 + 4 , 5 =","hiện 17"],["200 × 15 % =","hiện 30 (tức 15% của 200)"],["7 500 ÷ 100 =","hiện 75"],["C","xoá để nhập phép tính mới"]],"label":"Luôn ước lượng trước để kiểm tra kết quả máy hiện ra"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bảng nhân – bảng chia – phân số đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Xác định đề hỏi nhân hay chia (chia luôn tra ngược bảng nhân).","Bước 2 — Tách số thành hàng chục và hàng đơn vị rồi tính từng phần.","Bước 3 — Cộng các phần lại, nhớ cộng số nhớ khi có.","Bước 4 — Thử lại bằng phép ngược (nhân ↔ chia) hoặc bằng tổng."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Nhân với 10","thêm một chữ số 0"],["Chia hết","số dư bằng 0"],["Phân số","mẫu số chia đều thành mấy phần, tử số lấy mấy phần"]]},"text":"Bảng nhớ nhanh — bảng nhân – bảng chia – phân số\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Muốn tính 24 : 6, bé dựa vào đâu cho nhanh?","options":["Tra ngược bảng nhân 6","Đếm lùi 24 lần","Cộng 6 vào 24","Bấm máy tính"],"answer":"Tra ngược bảng nhân 6","mascotHint":"Vì 6 × 4 = 24 nên 24 : 6 = 4 — tra bảng nhân bao giờ cũng nhanh hơn đếm."}},{"type":"quiz","content":{"question":"Bấm 12 , 5 + 4 , 5 = thì máy hiện kết quả nào?","options":["17","17,5","16","1,7"],"answer":"17","mascotHint":"12,5 + 4,5 = 17."}},{"type":"quiz","content":{"question":"Muốn nhập số 3,75 vào máy tính cầm tay, em bấm thế nào?","options":["Bấm 3, dấu phẩy, 7, 5","Bấm 3, 7, 5","Bấm 3, 7, dấu phẩy, 5","Bấm 3, dấu chấm, 7, 5 trên bàn phím chữ"],"answer":"Bấm 3, dấu phẩy, 7, 5","mascotHint":"Dấu phẩy dùng để ngăn cách phần nguyên và phần thập phân."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Máy tính cầm tay có phím số, phím phép tính, phím %.","Nhập số thập phân bằng phím dấu phẩy.","Ước lượng kết quả để kiểm tra."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l8', 'g5-c7', 'Bài 43: Thực hành và trải nghiệm sử dụng máy tính cầm tay', 'learn', 'Dùng máy tính cầm tay giải các bài toán thực tế về mua bán, phần trăm', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hôm nay cả lớp đi siêu thị và dùng máy tính cầm tay để tính tiền. Vừa học vừa trải nghiệm thật vui! 🛒"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Dùng máy tính giải bài toán thực tế","explanation":"Khi mua hàng, ta cần tính tổng số tiền, số tiền giảm giá và số tiền còn lại. Máy tính cầm tay giúp tính nhanh, nhưng ta vẫn phải viết phép tính ra giấy để trình bày cách làm.","points":["Tính tiền từng món: số lượng × giá tiền.","Tính tiền giảm giá: giá gốc × số phần trăm : 100.","Kiểm tra kết quả bằng ước lượng tròn trăm, tròn nghìn."],"rule":"Máy tính chỉ hỗ trợ tính nhanh — vẫn phải hiểu cách làm."}},{"type":"visual","content":{"text":"Bảng tính tiền đi siêu thị","table":{"headers":["Mặt hàng","Số lượng","Đơn giá (đồng)","Thành tiền"],"rows":[["Vở",5,"9 000","45 000"],["Bút chì",3,"6 000","18 000"],["Thước kẻ",1,"15 000","15 000"],["Tổng cộng","","","78 000"]],"label":"Dùng máy tính kiểm tra lại cột thành tiền"}}},{"type":"concept","content":{"badge":"Cách Học","title":"Bốn bước làm một bài toán","explanation":"Mọi bài bài toán có lời văn đều đi theo cùng một đường. Bé làm đúng thứ tự thì không bỏ sót bước nào.","points":["Bước 1 — Đọc kỹ đề, gạch dưới các SỐ và từ khoá (thêm, bớt, gấp, chia đều).","Bước 2 — Tóm tắt đề bằng hình hoặc bằng câu ngắn: đã có gì, cần tìm gì.","Bước 3 — Chọn phép tính: “thêm, gộp, tất cả” → cộng; “bớt, cho đi, còn lại” → trừ; “gấp mấy lần” → nhân.","Bước 4 — Đặt tính rồi tính, rồi VIẾT ĐÁP SỐ kèm đơn vị và thử lại bằng phép ngược."]}},{"type":"visual","content":{"table":{"headers":["Điều cần nhớ","Nội dung"],"rows":[["Đơn vị","đáp số luôn kèm đơn vị như con, quả, kg, cm"],["Kiểm tra","cộng thì lấy kết quả trừ đi một số hạng"],["Câu trả lời","viết đủ câu, không chỉ ghi số"]]},"text":"Bảng nhớ nhanh — bài toán có lời văn\nBa điều dưới đây bé đọc lại mỗi khi làm bài.\nTrước khi nộp bài, bé tự hỏi: đã đủ ba điều này chưa?"}},{"type":"quiz","content":{"question":"Giải một bài toán có lời văn, bé làm gì TRƯỚC TIÊN?","options":["Đọc kỹ đề và gạch dưới các số đã cho","Viết ngay đáp số","Đoán kết quả","Đặt tính trước khi đọc đề"],"answer":"Đọc kỹ đề và gạch dưới các số đã cho","mascotHint":"Chưa đọc kỹ đề thì chưa biết đề cho gì, hỏi gì — mọi bước sau đều dễ sai."}},{"type":"quiz","content":{"question":"Mua 5 quyển vở, mỗi quyển 9 000 đồng. Tổng số tiền phải trả là:","options":["45 000 đồng","14 000 đồng","54 000 đồng","4 500 đồng"],"answer":"45 000 đồng","mascotHint":"5 × 9 000 = 45 000 (đồng)."}},{"type":"quiz","content":{"question":"Một món hàng giá 200 000 đồng được giảm 20%. Số tiền phải trả là:","options":["160 000 đồng","180 000 đồng","20 000 đồng","140 000 đồng"],"answer":"160 000 đồng","mascotHint":"Giảm 200 000 : 100 × 20 = 40 000 đồng; 200 000 − 40 000 = 160 000 (đồng)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Tính thành tiền = số lượng × đơn giá.","Tính tiền giảm theo phần trăm.","Dùng máy tính để kiểm tra, không thay thế suy nghĩ."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c7-l9', 'g5-c7', 'Bài 44: Luyện tập chung', 'learn', 'Luyện tập tỉ số, tỉ số phần trăm, tỉ lệ bản đồ và hai bài toán tổng – tỉ, hiệu – tỉ', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Cùng ôn tập toàn bộ Chủ đề 7 — chủ đề “đắt khách” nhất trong các bài kiểm tra! 🎯"}},{"type":"visual","content":{"text":"Bảng tổng hợp Chủ đề 7","table":{"headers":["Nội dung","Cách làm"],"rows":[["Tỉ số, tỉ số phần trăm","a : b; thương × 100%"],["Tỉ lệ bản đồ","độ dài thật = bản đồ × mẫu số"],["Tổng – tỉ","tổng : tổng số phần"],["Hiệu – tỉ","hiệu : hiệu số phần"],["Giá trị phần trăm","số : 100 × số phần trăm"]],"label":"Vẽ sơ đồ khi làm bài toán tổng – tỉ, hiệu – tỉ"}}},{"type":"visual","content":{"cotTinh":{"left":12,"right":3,"sign":"×","remember":true},"text":"Bé tự đặt tính: 12 × 3\nhàng đơn vị 2 × 3 = 6, viết 6\nhàng chục 1 × 3 = 3, viết 3\nVậy 12 × 3 = 36."}},{"type":"quiz","content":{"question":"31 × 3 bằng bao nhiêu?","options":[92,93,94,95],"answer":93,"mascotHint":"hàng đơn vị 1 × 3 = 3, viết 3. Kết quả 93."}},{"type":"quiz","content":{"question":"Tìm tỉ số phần trăm của 45 và 50:","options":["90%","45%","50%","95%"],"answer":"90%","mascotHint":"45 : 50 × 100 = 90%."}},{"type":"quiz","content":{"question":"Tổng hai số là 60, tỉ số là 2/3. Số lớn là:","options":["36","24","30","40"],"answer":"36","mascotHint":"Tổng số phần 5 ⇒ một phần 12 ⇒ số lớn 12 × 3 = 36."}},{"type":"quiz","content":{"question":"25% của 480 kg là:","options":["120 kg","96 kg","240 kg","125 kg"],"answer":"120 kg","mascotHint":"480 : 100 × 25 = 120 (kg)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Phân biệt tổng – tỉ và hiệu – tỉ.","Tính phần trăm theo công thức.","Đổi đơn vị khi dùng tỉ lệ bản đồ."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c8-l1', 'g5-c8', 'Bài 45: Thể tích của một hình', 'learn', 'Nhận biết thể tích của một hình qua việc so sánh bằng các hình lập phương nhỏ', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Chiếc hộp nào chứa được nhiều hơn: hộp đựng 8 khối lập phương hay hộp đựng 12 khối? Hình nào chiếm nhiều không gian hơn thì có thể tích lớn hơn! 🧊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Thể tích của một hình","explanation":"Thể tích của một hình là lượng không gian mà hình đó chiếm chỗ. Ta có thể so sánh thể tích hai hình bằng cách đếm xem mỗi hình gồm bao nhiêu hình lập phương nhỏ như nhau.","points":["Hình nào gồm nhiều hình lập phương nhỏ hơn thì thể tích lớn hơn.","Hình lập phương cạnh 1 cm có thể tích là 1 xăng-ti-mét khối.","Hai hình bằng nhau thì có thể tích bằng nhau."],"rule":"Thể tích là phần không gian mà hình chiếm chỗ."}},{"type":"visual","content":{"text":"So sánh thể tích bằng khối lập phương nhỏ","table":{"headers":["Hình","Số khối lập phương nhỏ","So sánh"],"rows":[["Hình A",8,"Thể tích bé hơn"],["Hình B",12,"Thể tích lớn hơn"],["Hình C",12,"Bằng thể tích hình B"]],"label":"Các khối lập phương dùng để so sánh phải bằng nhau"}}},{"type":"visual","content":{"table":{"headers":["Đơn vị","Bằng bao nhiêu đơn vị liền sau"],"rows":[["1 m","10 dm"],["1 dm","10 cm"],["1 cm","10 mm"]]},"text":"Bậc thang đơn vị đo độ dài\n· m\n· dm\n· cm\n· mm\nĐi XUỐNG một bậc thì nhân hệ số của bậc đó; đi LÊN một bậc thì chia."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đổi đơn vị đo độ dài","explanation":"Bé chỉ cần nhớ đúng BẬC THANG đơn vị rồi nhân hoặc chia theo hệ số của từng bậc.","points":["1 m = 10 dm.","Đi xuống hai bậc thì nhân hai lần: 1 m = 10 × 10 = 100 cm.","Đổi số lớn ra số bé: NHÂN. Ví dụ 2 m = 20 dm.","Đổi số bé ra số lớn: CHIA. Ví dụ 30 dm = 3 m."]}},{"type":"quiz","content":{"question":"1 m bằng bao nhiêu dm?","options":[1,10,11,100],"answer":10,"mascotHint":"Hai đơn vị liền nhau: 1 m = 10 dm."}},{"type":"quiz","content":{"question":"3 m bằng bao nhiêu dm?","options":[10,30,40,300],"answer":30,"mascotHint":"Đổi số lớn ra số bé thì nhân: 3 × 10 = 30."}},{"type":"quiz","content":{"question":"Hình A gồm 8 khối lập phương nhỏ, hình B gồm 12 khối như thế. Hình nào có thể tích lớn hơn?","options":["Hình B","Hình A","Bằng nhau","Không so sánh được"],"answer":"Hình B","mascotHint":"12 khối nhiều hơn 8 khối nên hình B chiếm nhiều không gian hơn."}},{"type":"quiz","content":{"question":"Thể tích của một hình là gì?","options":["Phần không gian mà hình đó chiếm chỗ","Độ dài đường bao quanh hình","Số mặt của hình","Số đỉnh của hình"],"answer":"Phần không gian mà hình đó chiếm chỗ","mascotHint":"Thể tích nói về không gian hình chiếm, khác với chu vi, diện tích."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Thể tích là lượng không gian hình chiếm chỗ.","So sánh thể tích bằng cách đếm khối lập phương nhỏ.","Hình bằng nhau thì thể tích bằng nhau."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c8-l2', 'g5-c8', 'Bài 46: Xăng-ti-mét khối. Đề-xi-mét khối', 'learn', 'Nhận biết đơn vị đo thể tích cm³, dm³ và quan hệ 1 dm³ = 1 000 cm³', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Một khối lập phương cạnh 1 cm có thể tích 1 cm³. Khối lập phương cạnh 1 dm thì thể tích lớn hơn rất nhiều: 1 dm³ = 1 000 cm³! 📦"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Xăng-ti-mét khối và đề-xi-mét khối","explanation":"Xăng-ti-mét khối là thể tích của hình lập phương có cạnh dài 1 cm, viết tắt là cm³. Đề-xi-mét khối là thể tích của hình lập phương có cạnh dài 1 dm, viết tắt là dm³.","points":["1 dm³ = 1 000 cm³.","1 dm³ còn được gọi là 1 lít: 1 dm³ = 1 l.","Thể tích nước trong chai 1 lít là 1 dm³."],"rule":"1 dm³ = 1 000 cm³ = 1 lít."}},{"type":"visual","content":{"text":"Quan hệ giữa cm³ và dm³","table":{"headers":["Đơn vị","Cạnh của hình lập phương","Quan hệ"],"rows":[["1 cm³","1 cm","đơn vị bé"],["1 dm³","1 dm","1 dm³ = 1 000 cm³"],["1 lít","1 dm cạnh","1 l = 1 dm³ = 1 000 cm³"]],"label":"Đơn vị đo thể tích liền kề hơn kém nhau 1 000 lần"}}},{"type":"visual","content":{"table":{"headers":["Đơn vị","Bằng bao nhiêu đơn vị liền sau"],"rows":[["1 m","10 dm"],["1 dm","10 cm"],["1 cm","10 mm"]]},"text":"Bậc thang đơn vị đo độ dài\n· m\n· dm\n· cm\n· mm\nĐi XUỐNG một bậc thì nhân hệ số của bậc đó; đi LÊN một bậc thì chia."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đổi đơn vị đo độ dài","explanation":"Bé chỉ cần nhớ đúng BẬC THANG đơn vị rồi nhân hoặc chia theo hệ số của từng bậc.","points":["1 m = 10 dm.","Đi xuống hai bậc thì nhân hai lần: 1 m = 10 × 10 = 100 cm.","Đổi số lớn ra số bé: NHÂN. Ví dụ 2 m = 20 dm.","Đổi số bé ra số lớn: CHIA. Ví dụ 30 dm = 3 m."]}},{"type":"quiz","content":{"question":"1 m bằng bao nhiêu dm?","options":[1,10,11,100],"answer":10,"mascotHint":"Hai đơn vị liền nhau: 1 m = 10 dm."}},{"type":"quiz","content":{"question":"3 m bằng bao nhiêu dm?","options":[10,30,40,300],"answer":30,"mascotHint":"Đổi số lớn ra số bé thì nhân: 3 × 10 = 30."}},{"type":"quiz","content":{"question":"1 dm³ bằng bao nhiêu xăng-ti-mét khối?","options":["1 000 cm³","100 cm³","10 cm³","10 000 cm³"],"answer":"1 000 cm³","mascotHint":"Mỗi đơn vị đo thể tích liền kề hơn kém nhau 1 000 lần."}},{"type":"quiz","content":{"question":"3 dm³ bằng bao nhiêu xăng-ti-mét khối?","options":["3 000 cm³","300 cm³","30 cm³","30 000 cm³"],"answer":"3 000 cm³","mascotHint":"3 × 1 000 = 3 000 (cm³)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["cm³ là thể tích hình lập phương cạnh 1 cm.","dm³ là thể tích hình lập phương cạnh 1 dm.","1 dm³ = 1 000 cm³ = 1 lít."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c8-l3', 'g5-c8', 'Bài 47: Mét khối', 'learn', 'Nhận biết mét khối (m³) và quan hệ với dm³, cm³, lít', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bể bơi ở trường chứa được 60 m³ nước. 1 m³ là thể tích của hình lập phương cạnh 1 m — to bằng cả một chiếc thùng lớn! 🏊"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Mét khối","explanation":"Mét khối là thể tích của hình lập phương có cạnh dài 1 m, viết tắt là m³. Mét khối được dùng để đo thể tích của những vật lớn như bể nước, căn phòng, thùng hàng.","points":["1 m³ = 1 000 dm³.","1 m³ = 1 000 000 cm³.","1 m³ = 1 000 lít."],"rule":"Đơn vị đo thể tích lớn hơn liền trước gấp 1 000 lần."}},{"type":"visual","content":{"text":"Quan hệ giữa các đơn vị đo thể tích","table":{"headers":["Đơn vị","Quan hệ"],"rows":[["1 m³","1 000 dm³"],["1 dm³","1 000 cm³"],["1 m³","1 000 000 cm³"],["1 m³","1 000 lít"]],"label":"Mỗi bậc đổi 1 000 lần"}}},{"type":"visual","content":{"table":{"headers":["Đơn vị","Bằng bao nhiêu đơn vị liền sau"],"rows":[["1 m³","1000 dm³"],["1 dm³","1000 cm³"]]},"text":"Bậc thang đơn vị đo thể tích\n· m³\n· dm³\n· cm³\nĐi XUỐNG một bậc thì nhân hệ số của bậc đó; đi LÊN một bậc thì chia."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đổi đơn vị đo thể tích","explanation":"Bé chỉ cần nhớ đúng BẬC THANG đơn vị rồi nhân hoặc chia theo hệ số của từng bậc.","points":["1 m³ = 1000 dm³.","Đi xuống hai bậc thì nhân hai lần: 1 m³ = 1000 × 1000 = 1000000 cm³.","Đổi số lớn ra số bé: NHÂN. Ví dụ 2 m³ = 2000 dm³.","Đổi số bé ra số lớn: CHIA. Ví dụ 3000 dm³ = 3 m³."]}},{"type":"quiz","content":{"question":"1 m³ bằng bao nhiêu dm³?","options":[100,1000,10000,1000000],"answer":1000,"mascotHint":"Hai đơn vị liền nhau: 1 m³ = 1000 dm³."}},{"type":"quiz","content":{"question":"3 m³ bằng bao nhiêu dm³?","options":[1000,3000,4000,30000],"answer":3000,"mascotHint":"Đổi số lớn ra số bé thì nhân: 3 × 1000 = 3000."}},{"type":"quiz","content":{"question":"1 m³ bằng bao nhiêu đề-xi-mét khối?","options":["1 000 dm³","100 dm³","10 000 dm³","10 dm³"],"answer":"1 000 dm³","mascotHint":"Hình lập phương cạnh 1 m chứa được 10 × 10 × 10 = 1 000 hình lập phương cạnh 1 dm."}},{"type":"quiz","content":{"question":"Bể bơi chứa 60 m³ nước. Số nước đó tương ứng bao nhiêu lít?","options":["60 000 lít","6 000 lít","600 lít","600 000 lít"],"answer":"60 000 lít","mascotHint":"1 m³ = 1 000 lít nên 60 m³ = 60 000 lít."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["1 m³ = 1 000 dm³.","1 dm³ = 1 000 cm³.","1 m³ = 1 000 lít."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c8-l4', 'g5-c8', 'Bài 48: Luyện tập chung', 'learn', 'Luyện tập đổi đơn vị đo thể tích và so sánh thể tích', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Một thùng chứa 2,5 m³ nước tức là 2 500 dm³. Cùng luyện tập đổi đơn vị đo thể tích nhé! 🛢️"}},{"type":"visual","content":{"text":"Luyện tập đổi đơn vị đo thể tích","table":{"headers":["Số đo","Đổi đơn vị"],"rows":[["2,5 m³","2 500 dm³"],["3 000 cm³","3 dm³"],["0,5 m³","500 dm³"],["7 dm³","7 000 cm³"]],"label":"Đổi từ lớn sang bé thì nhân 1 000"}}},{"type":"visual","content":{"table":{"headers":["Đơn vị","Bằng bao nhiêu đơn vị liền sau"],"rows":[["1 m³","1000 dm³"],["1 dm³","1000 cm³"]]},"text":"Bậc thang đơn vị đo thể tích\n· m³\n· dm³\n· cm³\nĐi XUỐNG một bậc thì nhân hệ số của bậc đó; đi LÊN một bậc thì chia."}},{"type":"concept","content":{"badge":"Mẹo Nhớ","title":"Cách đổi đơn vị đo thể tích","explanation":"Bé chỉ cần nhớ đúng BẬC THANG đơn vị rồi nhân hoặc chia theo hệ số của từng bậc.","points":["1 m³ = 1000 dm³.","Đi xuống hai bậc thì nhân hai lần: 1 m³ = 1000 × 1000 = 1000000 cm³.","Đổi số lớn ra số bé: NHÂN. Ví dụ 2 m³ = 2000 dm³.","Đổi số bé ra số lớn: CHIA. Ví dụ 3000 dm³ = 3 m³."]}},{"type":"quiz","content":{"question":"1 m³ bằng bao nhiêu dm³?","options":[100,1000,10000,1000000],"answer":1000,"mascotHint":"Hai đơn vị liền nhau: 1 m³ = 1000 dm³."}},{"type":"quiz","content":{"question":"3 m³ bằng bao nhiêu dm³?","options":[1000,3000,4000,30000],"answer":3000,"mascotHint":"Đổi số lớn ra số bé thì nhân: 3 × 1000 = 3000."}},{"type":"quiz","content":{"question":"3 000 cm³ bằng bao nhiêu đề-xi-mét khối?","options":["3 dm³","30 dm³","300 dm³","0,3 dm³"],"answer":"3 dm³","mascotHint":"3 000 : 1 000 = 3 (dm³)."}},{"type":"quiz","content":{"question":"Sắp xếp các số đo 2 dm³; 500 cm³; 1 dm³ theo thứ tự từ bé đến lớn:","options":["500 cm³; 1 dm³; 2 dm³","1 dm³; 500 cm³; 2 dm³","2 dm³; 1 dm³; 500 cm³","500 cm³; 2 dm³; 1 dm³"],"answer":"500 cm³; 1 dm³; 2 dm³","mascotHint":"Đổi về cùng đơn vị: 500 cm³ = 0,5 dm³ < 1 dm³ < 2 dm³."}},{"type":"quiz","content":{"question":"0,5 m³ bằng bao nhiêu đề-xi-mét khối?","options":["500 dm³","50 dm³","5 000 dm³","5 dm³"],"answer":"500 dm³","mascotHint":"0,5 × 1 000 = 500 (dm³)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Mỗi bậc đơn vị thể tích đổi 1 000 lần.","Đổi về cùng đơn vị trước khi so sánh.","1 dm³ = 1 lít."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c9-l1', 'g5-c9', 'Bài 49: Hình khai triển của hình lập phương, hình hộp chữ nhật và hình trụ', 'learn', 'Nhận biết hình khai triển của hình lập phương, hình hộp chữ nhật và hình trụ', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"curious","text":"Cắt một chiếc hộp giấy rồi trải phẳng ra, Cú Mèo thấy 6 hình chữ nhật nối với nhau. Đó chính là hình khai triển của hình hộp! ✂️"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Hình khai triển","explanation":"Khi cắt một hình khối theo các cạnh rồi trải phẳng ra, ta được hình khai triển của hình khối đó. Từ hình khai triển, ta thấy rõ các mặt của hình khối.","points":["Hình hộp chữ nhật có 6 mặt, nên hình khai triển gồm 6 hình chữ nhật.","Hình lập phương có 6 mặt vuông bằng nhau.","Hình trụ có hai mặt tròn (đáy) và một mặt cong — khi trải ra được một hình chữ nhật và hai hình tròn."],"rule":"Hình khai triển cho thấy tất cả các mặt của hình khối."}},{"type":"visual","content":{"text":"Các mặt của hình hộp chữ nhật","solid":{"kind":"cuboid","dims":{"a":5,"b":4,"c":3},"label":"Hình hộp chữ nhật","formula":"6 mặt: 2 mặt đáy và 4 mặt bên"}}},{"type":"visual","content":{"solid":{"kind":"cube"},"text":"khối lập phương bé học hôm nay có gì đặc biệt?\n· 6 mặt đều là hình vuông bằng nhau\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối lập phương","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối lập phương.","points":["khối lập phương có 6 mặt đều là hình vuông bằng nhau.","khối lập phương có 8 đỉnh.","khối lập phương có 12 cạnh bằng nhau.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước làm bài — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","mascotHint":"Người tính giỏi luôn thử lại: cộng thì lấy kết quả trừ đi một số hạng."}},{"type":"quiz","content":{"question":"Hình nào có 6 mặt đều là hình vuông bằng nhau?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình khối lập phương và hình khối hộp chữ nhật và hình khối trụ và hình vuông và hình tròn và hình tam giác và hình chữ nhật. Hình nào có 8 đỉnh?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"Đáp án là khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Hình khai triển của hình lập phương gồm mấy hình vuông?","options":["6 hình vuông","4 hình vuông","8 hình vuông","12 hình vuông"],"answer":"6 hình vuông","mascotHint":"Hình lập phương có 6 mặt là 6 hình vuông bằng nhau."}},{"type":"quiz","content":{"question":"Hình trụ có những mặt nào?","options":["Hai mặt tròn và một mặt cong","Sáu mặt chữ nhật","Sáu mặt vuông","Bốn mặt tam giác"],"answer":"Hai mặt tròn và một mặt cong","mascotHint":"Hình trụ có hai đáy là hai hình tròn và mặt xung quanh là mặt cong."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Cắt và trải phẳng hình khối được hình khai triển.","Hình hộp chữ nhật và hình lập phương có 6 mặt.","Hình trụ có hai mặt tròn và một mặt cong."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c9-l2', 'g5-c9', 'Bài 50: Diện tích xung quanh và diện tích toàn phần của hình hộp chữ nhật', 'learn', 'Tính diện tích xung quanh và diện tích toàn phần của hình hộp chữ nhật', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Một chiếc hộp dài 5 cm, rộng 4 cm, cao 3 cm. Muốn dán giấy quanh hộp, cần biết diện tích xung quanh của hộp! 📦"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Diện tích xung quanh và toàn phần","explanation":"Diện tích xung quanh của hình hộp chữ nhật là tổng diện tích bốn mặt bên, bằng chu vi mặt đáy nhân với chiều cao. Diện tích toàn phần bằng diện tích xung quanh cộng với diện tích hai mặt đáy.","points":["Sxq = (a + b) × 2 × c (a, b là chiều dài, chiều rộng; c là chiều cao).","Stp = Sxq + a × b × 2.","Ví dụ a = 5 cm, b = 4 cm, c = 3 cm: 5 + 4 = 9 (cm); 9 × 2 = 18 (cm); 18 × 3 = 54 (cm²)."],"rule":"Sxq = chu vi mặt đáy × chiều cao."}},{"type":"visual","content":{"text":"Hình hộp chữ nhật dài 5 cm, rộng 4 cm, cao 3 cm","solid":{"kind":"cuboid","dims":{"a":5,"b":4,"c":3},"label":"Hình hộp chữ nhật","formula":"Sxq = chu vi đáy × cao = 18 × 3 = 54 (cm²)"}}},{"type":"visual","content":{"text":"Tính diện tích của hình hộp chữ nhật","table":{"headers":["Đại lượng","Phép tính","Kết quả"],"rows":[["Chu vi mặt đáy","(5 + 4) × 2","18 cm"],["Diện tích xung quanh","18 × 3","54 cm²"],["Diện tích một mặt đáy","5 × 4","20 cm²"],["Diện tích toàn phần","54 + 20 × 2","94 cm²"]],"label":"Stp = Sxq + diện tích hai đáy"}}},{"type":"visual","content":{"solid":{"kind":"cuboid"},"text":"khối hộp chữ nhật bé học hôm nay có gì đặc biệt?\n· 6 mặt, mỗi mặt là hình chữ nhật\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối hộp chữ nhật","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối hộp chữ nhật.","points":["khối hộp chữ nhật có 6 mặt, mỗi mặt là hình chữ nhật.","khối hộp chữ nhật có 8 đỉnh.","khối hộp chữ nhật có 12 cạnh.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước làm bài — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","mascotHint":"Người tính giỏi luôn thử lại: cộng thì lấy kết quả trừ đi một số hạng."}},{"type":"quiz","content":{"question":"Hình nào có 6 mặt, mỗi mặt là hình chữ nhật?","options":["khối hộp chữ nhật","hình khối lập phương","hình khối trụ","hình khối cầu"],"answer":"khối hộp chữ nhật","mascotHint":"khối hộp chữ nhật: 6 mặt, mỗi mặt là hình chữ nhật · 8 đỉnh · 12 cạnh."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình khối hộp chữ nhật và hình chữ nhật. Hình nào có 8 đỉnh?","options":["khối hộp chữ nhật","hình khối lập phương","hình khối trụ","hình khối cầu"],"answer":"khối hộp chữ nhật","mascotHint":"Đáp án là khối hộp chữ nhật: 6 mặt, mỗi mặt là hình chữ nhật · 8 đỉnh · 12 cạnh."}},{"type":"quiz","content":{"question":"Hình hộp chữ nhật dài 5 cm, rộng 4 cm, cao 3 cm có diện tích xung quanh là:","options":["54 cm²","60 cm²","27 cm²","94 cm²"],"answer":"54 cm²","mascotHint":"Sxq = (5 + 4) × 2 × 3 = 9 × 2 × 3 = 54 (cm²)."}},{"type":"quiz","content":{"question":"Diện tích toàn phần của hình hộp đó là bao nhiêu?","options":["94 cm²","54 cm²","74 cm²","108 cm²"],"answer":"94 cm²","mascotHint":"Stp = 54 + 5 × 4 × 2 = 54 + 40 = 94 (cm²)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Sxq = (dài + rộng) × 2 × cao.","Stp = Sxq + dài × rộng × 2.","Ghi đơn vị là cm², m²…"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c9-l3', 'g5-c9', 'Bài 51: Diện tích xung quanh và diện tích toàn phần của hình lập phương', 'learn', 'Tính diện tích xung quanh và diện tích toàn phần của hình lập phương', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Một khối lập phương cạnh 3 cm có 4 mặt bên giống nhau, mỗi mặt 9 cm². Vậy diện tích xung quanh là 36 cm²! 🎲"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Diện tích của hình lập phương","explanation":"Hình lập phương có 6 mặt là 6 hình vuông bằng nhau. Diện tích xung quanh bằng diện tích một mặt nhân với 4. Diện tích toàn phần bằng diện tích một mặt nhân với 6.","points":["Diện tích một mặt = a × a.","Sxq = a × a × 4.","Stp = a × a × 6."],"rule":"Với hình lập phương: Sxq = a × a × 4; Stp = a × a × 6."}},{"type":"visual","content":{"text":"Hình lập phương cạnh 3 cm","solid":{"kind":"cube","dims":{"a":3},"label":"Hình lập phương","formula":"Sxq = 3 × 3 × 4 = 36 cm²"}}},{"type":"visual","content":{"solid":{"kind":"cube"},"text":"khối lập phương bé học hôm nay có gì đặc biệt?\n· 6 mặt đều là hình vuông bằng nhau\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối lập phương","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối lập phương.","points":["khối lập phương có 6 mặt đều là hình vuông bằng nhau.","khối lập phương có 8 đỉnh.","khối lập phương có 12 cạnh bằng nhau.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước làm bài — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","mascotHint":"Người tính giỏi luôn thử lại: cộng thì lấy kết quả trừ đi một số hạng."}},{"type":"quiz","content":{"question":"Hình nào có 6 mặt đều là hình vuông bằng nhau?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình khối lập phương và hình vuông. Hình nào có 8 đỉnh?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"Đáp án là khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Hình lập phương cạnh 3 cm có diện tích xung quanh là:","options":["36 cm²","54 cm²","27 cm²","12 cm²"],"answer":"36 cm²","mascotHint":"Sxq = 3 × 3 × 4 = 36 (cm²)."}},{"type":"quiz","content":{"question":"Hình lập phương cạnh 3 cm có diện tích toàn phần là:","options":["54 cm²","36 cm²","27 cm²","45 cm²"],"answer":"54 cm²","mascotHint":"Stp = 3 × 3 × 6 = 54 (cm²)."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["Diện tích một mặt = a × a.","Sxq = a × a × 4.","Stp = a × a × 6."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c9-l4', 'g5-c9', 'Bài 52: Thể tích của hình hộp chữ nhật', 'learn', 'Tính thể tích hình hộp chữ nhật: V = a × b × c', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Muốn biết chiếc hộp chứa được bao nhiêu nước, cần tính thể tích. Hộp dài 5 cm, rộng 4 cm, cao 3 cm chứa được 60 cm³! 🚰"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Thể tích hình hộp chữ nhật","explanation":"Muốn tính thể tích hình hộp chữ nhật, ta lấy chiều dài nhân với chiều rộng rồi nhân với chiều cao (ba kích thước phải cùng đơn vị đo).","points":["V = a × b × c.","a = 5 cm, b = 4 cm, c = 3 cm ⇒ V = 5 × 4 × 3 = 60 cm³.","Thể tích là số hình lập phương 1 cm³ xếp đầy trong hộp."],"rule":"V = chiều dài × chiều rộng × chiều cao."}},{"type":"visual","content":{"text":"Thể tích hình hộp chữ nhật","solid":{"kind":"cuboid","dims":{"a":5,"b":4,"c":3},"label":"Hình hộp chữ nhật","formula":"V = 5 × 4 × 3 = 60 cm³"}}},{"type":"visual","content":{"solid":{"kind":"cube"},"text":"khối lập phương bé học hôm nay có gì đặc biệt?\n· 6 mặt đều là hình vuông bằng nhau\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối lập phương","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối lập phương.","points":["khối lập phương có 6 mặt đều là hình vuông bằng nhau.","khối lập phương có 8 đỉnh.","khối lập phương có 12 cạnh bằng nhau.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước làm bài — bé làm lần lượt\nBé đọc bảng này trước khi làm, và đọc lại sau khi làm xong.\nBỏ một bước là bài dễ sai."}},{"type":"quiz","content":{"question":"Làm xong một bài, bé nên làm gì để chắc chắn kết quả đúng?","options":["Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","Nộp bài luôn cho nhanh","Đoán lại một lần nữa"],"answer":"Thử lại bằng phép tính ngược hoặc kiểm tra theo điều cần nhớ","mascotHint":"Người tính giỏi luôn thử lại: cộng thì lấy kết quả trừ đi một số hạng."}},{"type":"quiz","content":{"question":"Hình nào có 6 mặt đều là hình vuông bằng nhau?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Trong bài hôm nay có hình khối lập phương và hình khối hộp chữ nhật và hình chữ nhật. Hình nào có 8 đỉnh?","options":["khối lập phương","hình khối hộp chữ nhật","hình khối trụ","hình khối cầu"],"answer":"khối lập phương","mascotHint":"Đáp án là khối lập phương: 6 mặt đều là hình vuông bằng nhau · 8 đỉnh · 12 cạnh bằng nhau."}},{"type":"quiz","content":{"question":"Hình hộp chữ nhật dài 5 cm, rộng 4 cm, cao 3 cm có thể tích là:","options":["60 cm³","54 cm³","12 cm³","94 cm³"],"answer":"60 cm³","mascotHint":"V = 5 × 4 × 3 = 60 (cm³)."}},{"type":"quiz","content":{"question":"Một bể cá dài 6 dm, rộng 4 dm, cao 3 dm. Thể tích bể cá là:","options":["72 dm³","24 dm³","13 dm³","144 dm³"],"answer":"72 dm³","mascotHint":"V = 6 × 4 × 3 = 72 (dm³) = 72 lít nước."}},{"type":"summary","content":{"title":"Ghi nhớ bài học:","points":["V = dài × rộng × cao.","Ba kích thước cùng đơn vị đo.","1 dm³ = 1 lít nên thể tích bể đổi ra lít rất tiện."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c9-l5', 'g5-c9', 'Bài 53: Thể tích của hình lập phương', 'learn', 'Tính thể tích hình lập phương: V = a × a × a', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Khối lập phương cạnh 3 cm: thể tích là 3 × 3 × 3 = 27 cm³. Nhớ công thức “cạnh nhân cạnh nhân cạnh”! 🎲"}},{"type":"concept","content":{"badge":"Khám Phá","title":"Thể tích hình lập phương","explanation":"Hình lập phương có ba kích thước bằng nhau. Muốn tính thể tích hình lập phương, ta lấy cạnh nhân với cạnh rồi nhân với cạnh.","points":["V = a × a × a.","a = 3 cm ⇒ V = 3 × 3 × 3 = 27 cm³.","a = 2 dm ⇒ V = 2 × 2 × 2 = 8 dm³."],"rule":"V = cạnh × cạnh × cạnh."}},{"type":"visual","content":{"text":"Thể tích hình lập phương cạnh 3 cm","table":{"headers":["Đại lượng","Phép tính","Kết quả"],"rows":[["Diện tích một mặt","3 × 3","9 cm²"],["Diện tích xung quanh","9 × 4","36 cm²"],["Diện tích toàn phần","9 × 6","54 cm²"],["Thể tích","3 × 3 × 3","27 cm³"]],"label":"Diện tích dùng cm², thể tích dùng cm³"}}},{"type":"visual","content":{"solid":{"kind":"cube"},"text":"khối lập phương bé học hôm nay có gì đặc biệt?\n· 6 mặt đều là hình vuông bằng nhau\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối lập phương","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối lập phương.","points":["khối lập phương có 6 mặt đều là hình vuông bằng nhau.","khối lập phương có 8 đỉnh.","khối lập phương có 12 cạnh bằng nhau.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"visual","content":{"table":{"headers":["Bước","Việc bé làm"],"rows":[["Bước 1 — Gọi tên","nói đúng tên hình/khối trước khi làm gì tiếp"],["Bước 2 — Đếm","đếm cạnh, đếm đỉnh rồi so với đặc điểm đã học"],["Bước 3 — Kiểm tra","dùng ê-ke hoặc thước để kiểm lại, không đoán bằng mắt"]]},"text":"Ba bước 