  ('g5-c9-l6', 'g5-c9', 'Bài 54: Thực hành tính toán và ước lượng thể tích một số hình khối', 'learn', 'Ứng dụng tính và ước lượng thể tích vào đồ vật quanh em', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hộp sữa dài 5 cm, rộng 4 cm, cao 10 cm ⇒ thể tích 200 cm³. Xếp đầy hộp bằng các khối 1 cm³ sẽ cần 200 khối! 📦"}},{"type":"concept","content":{"badge":"Thực Hành","title":"Tính và ước lượng thể tích","explanation":"Trong thực hành, ta đo ba kích thước của đồ vật rồi tính thể tích. Khi chưa đo chính xác, ta có thể ước lượng bằng cách làm tròn kích thước để biết thể tích khoảng bao nhiêu.","points":["Đo chiều dài, chiều rộng, chiều cao cùng đơn vị.","Tính thể tích theo công thức phù hợp với hình.","Ước lượng bằng cách làm tròn các kích thước."],"rule":"Thể tích của vật lớn dùng đơn vị lớn (m³, dm³)."}},{"type":"visual","content":{"text":"Tính thể tích một số đồ vật","table":{"headers":["Đồ vật","Kích thước","Thể tích"],"rows":[["Hộp sữa","5 cm × 4 cm × 10 cm","200 cm³"],["Bể cá","6 dm × 4 dm × 3 dm","72 dm³"],["Thùng hàng","1 m × 0,8 m × 0,5 m","0,4 m³"]],"label":"0,4 m³ = 400 dm³ = 400 lít"}}},{"type":"visual","content":{"solid":{"kind":"cuboid"},"text":"khối hộp chữ nhật bé học hôm nay có gì đặc biệt?\n· 6 mặt, mỗi mặt là hình chữ nhật\n· 8 đỉnh\nBé đếm mặt, đếm đỉnh, đếm cạnh ngay trên hình vẽ rồi đọc lại hai đặc điểm trên nhé."}},{"type":"concept","content":{"badge":"Ghi Nhớ","title":"Đặc điểm của khối hộp chữ nhật","explanation":"Nhìn hình và gọi tên đúng là bước đầu; bước sau là nêu được đặc điểm của khối hộp chữ nhật.","points":["khối hộp chữ nhật có 6 mặt, mỗi mặt là hình chữ nhật.","khối hộp chữ nhật có 8 đỉnh.","khối hộp chữ nhật có 12 cạnh.","Cách kiểm tra: bé đếm mặt, đếm đỉnh, đếm cạnh; nếu đếm ra khác các đặc điểm trên thì đã nhìn nhầm hình."]}},{"type":"quiz","content":{"question":"Hình nào có 6 mặt, mỗi mặt là hình chữ nhật?","options":["khối hộp chữ nhật","hình khối lập phương","hình khối trụ","hình khối cầu"],